// Normalize incoming alert to a standard format.
// Supports: Splunk, Elastic/Kibana, AWS GuardDuty, Wazuh, Suricata, generic.
const body = $input.first().json;

const alert = {
  alert_id:     body.id || body.alert_id || body.event_id || `alert-${Date.now()}`,
  alert_type:   body.type || body.alert_type || body.rule?.name || body.name || 'Unknown Alert',
  severity_raw: String(body.severity || body.priority || body.level || body.risk_score || 'medium').toLowerCase(),
  source_ip:    body.src_ip || body.source?.ip || body.srcIp || body.remote_ip || '',
  dest_ip:      body.dest_ip || body.destination?.ip || body.destIp || body.local_ip || '',
  hostname:     body.hostname || body.host?.name || body.agent?.name || body.computer || 'unknown-host',
  username:     body.user || body.username || body.user?.name || '',
  process_name: body.process || body.process_name || body.Image || '',
  description:  body.description || body.message || body.summary || body.rule?.description || '',
  raw_event:    JSON.stringify(body).slice(0, 2000),
  timestamp:    body.timestamp || body['@timestamp'] || new Date().toISOString(),
  source_system: body.source_system || body.manager?.name || 'Unknown SIEM',
};

return [{ json: alert }];

