const claudeRaw = $input.first().json;
const alert = $('Normalize Alert').first().json;

const rawText = claudeRaw.content?.[0]?.text || '{}';

let analysis;
try {
  const jsonMatch = rawText.match(/```json\n?([\s\S]*?)\n?```/) || rawText.match(/(\{[\s\S]*\})/);
  analysis = JSON.parse(jsonMatch ? jsonMatch[1].trim() : rawText.trim());
} catch (e) {
  analysis = {
    severity: 'MEDIUM',
    confidence_score: 50,
    threat_type: 'Undetermined',
    mitre_technique: 'T0000',
    mitre_tactic: 'Unknown',
    threat_summary: 'Claude could not parse the alert. Manual review required. Raw: ' + rawText.slice(0, 200),
    immediate_actions: ['Review alert manually', 'Check source IP in threat intel', 'Escalate to senior analyst'],
    false_positive_likelihood: 'MEDIUM',
    recommended_escalation: true
  };
}

const severity = (analysis.severity || 'MEDIUM').toUpperCase();

return [{
  json: {
    ...alert,
    ...analysis,
    severity,
    incident_id: `INC-${Date.now()}`,
    analyzed_at: new Date().toISOString(),
    is_high_priority: ['CRITICAL', 'HIGH'].includes(severity),
    slack_color: severity === 'CRITICAL' ? 'danger' : severity === 'HIGH' ? 'warning' : 'good',
    jira_priority: severity === 'CRITICAL' ? 'Highest' : 'High'
  }
}];

